import OpenFin from '@openfin/core';

type PopupChannelFactory = () => Promise<OpenFin.ChannelProvider>;

interface PopupActionEntry<T> {
    handler: (event: T) => Promise<void>;
    registrationPromise?: Promise<void>;
    subscriberCount: number;
}

interface PopupChannelStore {
    channelPromise: Promise<OpenFin.ChannelProvider>;
    actions: Map<string, PopupActionEntry<any>>;
    destroyPromise: Promise<void> | null;
}

const popupChannelStores = new WeakMap<PopupChannelFactory, PopupChannelStore>();

const getOrCreateStore = (createChannel: PopupChannelFactory): PopupChannelStore => {
    const existingStore = popupChannelStores.get(createChannel);
    if (existingStore) {
        return existingStore;
    }

    const nextStore: PopupChannelStore = {
        channelPromise: createChannel(),
        actions: new Map(),
        destroyPromise: null
    };
    popupChannelStores.set(createChannel, nextStore);
    return nextStore;
};

/**
 * Handles the subscription lifecycle for popup channels. Enforces
 * only one active subscriber per createChannel callback.
 * @param createChannel
 * @param actionName
 * @param handler
 * @returns
 */
export const subscribePopupChannelAction = <T>(
    createChannel: PopupChannelFactory,
    actionName: string,
    handler: (event: T) => Promise<void>
): { channelPromise: Promise<OpenFin.ChannelProvider>; unsubscribe: () => void } => {
    const store = getOrCreateStore(createChannel);
    let actionEntry = store.actions.get(actionName) as PopupActionEntry<T> | undefined;

    if (!actionEntry) {
        actionEntry = { handler, subscriberCount: 0 };
        store.actions.set(actionName, actionEntry);
        actionEntry.registrationPromise = (async () => {
            const channel = await store.channelPromise;
            channel.register(actionName, async (event: T) => {
                await store.actions.get(actionName)?.handler(event);
            });
        })();
    }

    if (actionEntry.subscriberCount > 0) {
        throw new Error(
            `Duplicate popup channel subscription detected for action "${actionName}". ` +
                'Only one active subscriber is allowed per createChannel callback.'
        );
    }

    actionEntry.handler = handler;
    actionEntry.subscriberCount += 1;

    let unsubscribed = false;
    const unsubscribe = () => {
        if (unsubscribed) return;
        unsubscribed = true;

        const activeStore = popupChannelStores.get(createChannel);
        if (!activeStore) return;

        const activeActionEntry = activeStore.actions.get(actionName) as PopupActionEntry<T> | undefined;
        if (!activeActionEntry) return;

        activeActionEntry.subscriberCount = Math.max(0, activeActionEntry.subscriberCount - 1);
        if (activeActionEntry.subscriberCount > 0) return;

        activeStore.actions.delete(actionName);
        if (activeStore.actions.size > 0) return;

        popupChannelStores.delete(createChannel);
        if (activeStore.destroyPromise) return;

        activeStore.destroyPromise = activeStore.channelPromise
            .then((channel) => channel.destroy())
            .catch((error) => {
                console.error('Error destroying popup channel:', error);
            });
    };

    return { channelPromise: store.channelPromise, unsubscribe };
};
